Translate("frFR", "marvon-rivetseeker", {
	title = "Marvon Rivetseeker",
	found = "Le Pilier brisé, au milieu du désert",
	hint = [=[Cherchez l'érudit gobelin qui campe parmi les ruines trolls du désert.]=],
	allegiance = "Ratchet",
	aliases = { "Marvon" },
	sections = {
		{
			title = "Résumé",
			text = [=[Marvon Rivetseeker est un gobelin de {link:ratchet}Ratchet{/link}, un savant et, de son propre aveu, un chasseur de trésors dans l'âme. Il a étudié bien des lieux anciens du monde et campe désormais dans le désert pour en étudier les ruines trolls. Il collectionne les ornements de gahz'ridian, une pierre que les trolls sculptaient à la forme de leur dieu hydre, et il a construit un casque qui les détecte. Il entra un jour dans le {link:temple-of-atal-hakkar}Temple englouti{/link} et en réchappa de justesse. De son cercle de statues de serpents, il ne se rappelle que des fragments.]=],
		},
	},
	chapters = {
		{
			title = "Le cercle de pierre",
			hint = "Aidez l'érudit gobelin à se souvenir du Temple englouti.",
			text = [=[Marvon avait trouvé une pierre ronde marquée du même signe de serpent qu'il avait vu dans le temple, et l'avait expédiée à son atelier de {link:ratchet}Ratchet{/link}. Quand on la lui apporta, sa mémoire revint : six balcons, six statues de serpents, et un autel d'{link:hakkar}Hakkar{/link} en contrebas.]=],
		},
	},
	mentions = {
		{ text = "Gahz'ridian" },
		{ text = "Le {link:temple-of-atal-hakkar}Temple englouti{/link}" },
		{ text = "Dans les profondeurs" },
		{ text = "Le secret du cercle" },
	},
})

